import{_ as e,c as i,o as n,a0 as t}from"./chunks/framework.DKRgXLPU.js";const r=JSON.parse('{"title":"Leadership in Pétanque","description":"Develop leadership skills that elevate your team\'s performance. Learn how to lead effectively whether you\'re the captain or a supporting player.","frontmatter":{"title":"Leadership in Pétanque","description":"Develop leadership skills that elevate your team\'s performance. Learn how to lead effectively whether you\'re the captain or a supporting player."},"headers":[],"relativePath":"de/blog/team-leadership.md","filePath":"de/blog/team-leadership.md"}');const a=e({name:"de/blog/team-leadership.md"},[["render",function(e,r,a,l,h,u){return n(),i("div",null,[...r[0]||(r[0]=[t('<h1 id="fuhrung-im-petanque" tabindex="-1">Führung im Pétanque <a class="header-anchor" href="#fuhrung-im-petanque" aria-label="Permalink to &quot;Führung im Pétanque&quot;">​</a></h1><p>Führung im Pétanque bedeutet nicht nur, Kapitän oder bester Spieler zu sein. Es geht um Einflussnahme, Unterstützung und darum, das Beste aus dem Team herauszuholen. Jeder Spieler kann auf seine Weise führen.</p><h2 id="was-ist-petanque-fuhrung" tabindex="-1">Was ist Pétanque-Führung? <a class="header-anchor" href="#was-ist-petanque-fuhrung" aria-label="Permalink to &quot;Was ist Pétanque-Führung?&quot;">​</a></h2><p>Effektive Führung im Boule-Spiel bedeutet:</p><ul><li>Unter Druck gute Entscheidungen treffen</li><li>Teammitglieder bei Herausforderungen unterstützen</li><li>Teamfokus und Energie aufrechterhalten</li><li>Das gewünschte Verhalten modellieren</li><li>Verantwortung für die Ergebnisse des Teams übernehmen</li></ul><h2 id="fuhrungsstile" tabindex="-1">Führungsstile <a class="header-anchor" href="#fuhrungsstile" aria-label="Permalink to &quot;Führungsstile&quot;">​</a></h2><h3 id="positionelle-fuhrung" tabindex="-1">Positionelle Führung <a class="header-anchor" href="#positionelle-fuhrung" aria-label="Permalink to &quot;Positionelle Führung&quot;">​</a></h3><p>Der designierte Kapitän oder Teamleiter:</p><ul><li>Trifft endgültige strategische Entscheidungen</li><li>Vertritt das Team offiziell</li><li>Steuert die Teamdynamik</li><li>Prägt den Ton und die Kultur</li></ul><h3 id="leistungsfuhrung" tabindex="-1">Leistungsführung <a class="header-anchor" href="#leistungsfuhrung" aria-label="Permalink to &quot;Leistungsführung&quot;">​</a></h3><p>Führend durch Exzellenz:</p><ul><li>Geschicklichkeit und Beständigkeit unter Beweis stellen</li><li>Zeigen, wie man mit Druck umgeht</li><li>Standards durch Handeln setzen</li><li>Inspirierend durch Leistung</li></ul><h3 id="emotionale-fuhrung" tabindex="-1">Emotionale Führung <a class="header-anchor" href="#emotionale-fuhrung" aria-label="Permalink to &quot;Emotionale Führung&quot;">​</a></h3><p>Teamenergie und -moral managen:</p><ul><li>Auch unter Druck positiv bleiben</li><li>Unterstützung für Teamkollegen in schwierigen Situationen</li><li>Erfolge feiern</li><li>Die Perspektive bewahren</li></ul><h3 id="taktische-fuhrung" tabindex="-1">Taktische Führung <a class="header-anchor" href="#taktische-fuhrung" aria-label="Permalink to &quot;Taktische Führung&quot;">​</a></h3><p>Strategisches Denken einbringen:</p><ul><li>Das Spiel gut lesen</li><li>Bietet wertvolle Einblicke</li><li>Muster erkennen, die anderen entgehen</li><li>Vorausdenken</li></ul><h2 id="der-effektive-fuhrer" tabindex="-1">Der effektive Führer <a class="header-anchor" href="#der-effektive-fuhrer" aria-label="Permalink to &quot;Der effektive Führer&quot;">​</a></h2><h3 id="in-der-praxis" tabindex="-1">In der Praxis <a class="header-anchor" href="#in-der-praxis" aria-label="Permalink to &quot;In der Praxis&quot;">​</a></h3><ul><li>Kommt vorbereitet und konzentriert an.</li><li>Arbeitet hart und ermutigt andere</li><li>Gibt konstruktives Feedback</li><li>Schafft ein positives Trainingsumfeld</li></ul><h3 id="vor-dem-wettbewerb" tabindex="-1">Vor dem Wettbewerb <a class="header-anchor" href="#vor-dem-wettbewerb" aria-label="Permalink to &quot;Vor dem Wettbewerb&quot;">​</a></h3><ul><li>Stellt sicher, dass das Team vorbereitet ist</li><li>Schafft klare Erwartungen</li><li>Bewältigt die Nervosität vor dem Spiel</li><li>Schafft Konzentration und Selbstvertrauen</li></ul><h3 id="wahrend-des-wettbewerbs" tabindex="-1">Während des Wettbewerbs <a class="header-anchor" href="#wahrend-des-wettbewerbs" aria-label="Permalink to &quot;Während des Wettbewerbs&quot;">​</a></h3><ul><li>Trifft klare und zeitnahe Entscheidungen</li><li>Unterstützt Teamkollegen sichtbar</li><li>Bleibt auch unter Druck ruhig.</li><li>Passt die Strategie nach Bedarf an</li></ul><h3 id="nach-dem-wettbewerb" tabindex="-1">Nach dem Wettbewerb <a class="header-anchor" href="#nach-dem-wettbewerb" aria-label="Permalink to &quot;Nach dem Wettbewerb&quot;">​</a></h3><ul><li>Geht mit Siegen elegant um.</li><li>Geht mit Verlusten gelassen um.</li><li>Leitet konstruktive Nachbesprechungen</li><li>Pflegt die Beziehungen zum Team</li></ul><h2 id="fuhrungsherausforderungen" tabindex="-1">Führungsherausforderungen <a class="header-anchor" href="#fuhrungsherausforderungen" aria-label="Permalink to &quot;Führungsherausforderungen&quot;">​</a></h2><h3 id="schwierige-entscheidungen-treffen" tabindex="-1">Schwierige Entscheidungen treffen <a class="header-anchor" href="#schwierige-entscheidungen-treffen" aria-label="Permalink to &quot;Schwierige Entscheidungen treffen&quot;">​</a></h3><p>Manchmal muss man:</p><ul><li>Wählen Sie zwischen Optionen, bei denen es keine eindeutige Antwort gibt.</li><li>Mit Teamkollegen nicht einverstanden sein</li><li>Übernehmen Sie Verantwortung für die Ergebnisse.</li><li>Handeln Sie trotz Unsicherheit entschlossen.</li></ul><p><strong>Ansatz:</strong></p><ul><li>Schnell Input sammeln</li><li>Triff die Entscheidung</li><li>Sich voll und ganz engagieren</li><li>Aus den Ergebnissen lernen</li></ul><h3 id="konfliktmanagement" tabindex="-1">Konfliktmanagement <a class="header-anchor" href="#konfliktmanagement" aria-label="Permalink to &quot;Konfliktmanagement&quot;">​</a></h3><p>Teamreibung ist unvermeidlich:</p><ul><li>Unterschiedliche Meinungen zur Strategie</li><li>Frustration nach Fehlern</li><li>Persönlichkeitskonflikte</li><li>Ungleiches Engagement</li></ul><p><strong>Ansatz:</strong></p><ul><li>Probleme frühzeitig angehen</li><li>Hören Sie sich alle Perspektiven an.</li><li>Fokus auf Lösungen</li><li>Respektvoller Umgang</li></ul><h3 id="unterstutzung-von-spielern-in-schwierigkeiten" tabindex="-1">Unterstützung von Spielern in Schwierigkeiten <a class="header-anchor" href="#unterstutzung-von-spielern-in-schwierigkeiten" aria-label="Permalink to &quot;Unterstützung von Spielern in Schwierigkeiten&quot;">​</a></h3><p>Wenn ein Teammitglied unter seinen Möglichkeiten bleibt:</p><ul><li>Erhöhen Sie den Druck nicht.</li><li>Bieten Sie konkrete, positive Unterstützung an.</li><li>Strategie bei Bedarf anpassen</li><li>Bewahren Sie Ihr Vertrauen in sie</li></ul><h3 id="umgang-mit-den-eigenen-problemen" tabindex="-1">Umgang mit den eigenen Problemen <a class="header-anchor" href="#umgang-mit-den-eigenen-problemen" aria-label="Permalink to &quot;Umgang mit den eigenen Problemen&quot;">​</a></h3><p>Auch Führungskräfte haben mit Schwierigkeiten zu kämpfen:</p><ul><li>Akzeptiere es (dir selbst gegenüber)</li><li>Lassen Sie sich davon nicht in Ihrer Führungsrolle beeinträchtigen.</li><li>Stütze dich auf deine Teamkollegen</li><li>Modellresilienz</li></ul><h2 id="fuhrungsstile-1" tabindex="-1">Führungsstile <a class="header-anchor" href="#fuhrungsstile-1" aria-label="Permalink to &quot;Führungsstile&quot;">​</a></h2><h3 id="der-kommandant" tabindex="-1">Der Kommandant <a class="header-anchor" href="#der-kommandant" aria-label="Permalink to &quot;Der Kommandant&quot;">​</a></h3><ul><li>Direkt und entschlossen</li><li>Klare Erwartungen</li><li>Übernimmt in der Krise die Führung</li><li>Risiko: Kann erdrückend sein</li></ul><h3 id="der-trainer" tabindex="-1">Der Trainer <a class="header-anchor" href="#der-trainer" aria-label="Permalink to &quot;Der Trainer&quot;">​</a></h3><ul><li>Entwickelt andere</li><li>Stellt Fragen</li><li>Baut Fähigkeiten auf</li><li>Risiko: Kann in Krisenzeiten langsam reagieren.</li></ul><h3 id="der-mitarbeiter" tabindex="-1">Der Mitarbeiter <a class="header-anchor" href="#der-mitarbeiter" aria-label="Permalink to &quot;Der Mitarbeiter&quot;">​</a></h3><ul><li>Bittet um Feedback</li><li>Schafft Konsens</li><li>Schätzt alle Stimmen</li><li>Risiko: Kann unentschlossen sein</li></ul><h3 id="der-unterstutzer" tabindex="-1">Der Unterstützer <a class="header-anchor" href="#der-unterstutzer" aria-label="Permalink to &quot;Der Unterstützer&quot;">​</a></h3><ul><li>Fokus auf Beziehungen</li><li>Schafft Sicherheit</li><li>Ermutigt und bestärkt</li><li>Risiko: Kann unangenehme Wahrheiten vermeiden.</li></ul><p><strong>Die besten Führungskräfte passen ihren Führungsstil der jeweiligen Situation an.</strong></p><h2 id="entwicklung-von-fuhrungskompetenzen" tabindex="-1">Entwicklung von Führungskompetenzen <a class="header-anchor" href="#entwicklung-von-fuhrungskompetenzen" aria-label="Permalink to &quot;Entwicklung von Führungskompetenzen&quot;">​</a></h2><h3 id="selbstwahrnehmung" tabindex="-1">Selbstwahrnehmung <a class="header-anchor" href="#selbstwahrnehmung" aria-label="Permalink to &quot;Selbstwahrnehmung&quot;">​</a></h3><p>Kenne deine:</p><ul><li>Natürlicher Führungsstil</li><li>Stärken und Schwächen</li><li>Auswirkungen auf andere</li><li>Auslöser und Reaktionen</li></ul><h3 id="emotionale-intelligenz" tabindex="-1">Emotionale Intelligenz <a class="header-anchor" href="#emotionale-intelligenz" aria-label="Permalink to &quot;Emotionale Intelligenz&quot;">​</a></h3><p>Fähigkeit entwickeln, um:</p><ul><li>Emotionen erkennen (eigene und die anderer)</li><li>Verwalten Sie Ihre Antworten</li><li>Mit den Teamkollegen Empathie zeigen</li><li>Soziale Dynamiken verstehen</li></ul><h3 id="kommunikationsfahigkeit" tabindex="-1">Kommunikationsfähigkeit <a class="header-anchor" href="#kommunikationsfahigkeit" aria-label="Permalink to &quot;Kommunikationsfähigkeit&quot;">​</a></h3><p>Üben:</p><ul><li>Klare, prägnante Botschaften</li><li>Aktives Zuhören</li><li>Konstruktives Feedback geben</li><li>Schwierige Gespräche</li></ul><h3 id="entscheidungsfindung" tabindex="-1">Entscheidungsfindung <a class="header-anchor" href="#entscheidungsfindung" aria-label="Permalink to &quot;Entscheidungsfindung&quot;">​</a></h3><p>Verbessern durch:</p><ul><li>Analyse vergangener Entscheidungen</li><li>Ich bitte um Feedback</li><li>Aus Fehlern lernen</li><li>Üben unter Druck</li></ul><h2 id="fuhren-ohne-titel" tabindex="-1">Führen ohne Titel <a class="header-anchor" href="#fuhren-ohne-titel" aria-label="Permalink to &quot;Führen ohne Titel&quot;">​</a></h2><p>Man muss kein Kapitän sein, um zu führen:</p><h3 id="mit-gutem-beispiel-vorangehen" tabindex="-1">Mit gutem Beispiel vorangehen <a class="header-anchor" href="#mit-gutem-beispiel-vorangehen" aria-label="Permalink to &quot;Mit gutem Beispiel vorangehen&quot;">​</a></h3><ul><li>Erscheine vorbereitet</li><li>Gib dein Bestes</li><li>Gut mit Widrigkeiten umgehen</li><li>Unterstütze Teammitglieder</li></ul><h3 id="fuhren-durch-unterstutzung" tabindex="-1">Führen durch Unterstützung <a class="header-anchor" href="#fuhren-durch-unterstutzung" aria-label="Permalink to &quot;Führen durch Unterstützung&quot;">​</a></h3><ul><li>Ermutige andere</li><li>Biete Hilfe an</li><li>Feiert die Erfolge eurer Teamkollegen</li><li>Sei zuverlässig</li></ul><h3 id="fuhren-durch-beitrag" tabindex="-1">Führen durch Beitrag <a class="header-anchor" href="#fuhren-durch-beitrag" aria-label="Permalink to &quot;Führen durch Beitrag&quot;">​</a></h3><ul><li>Beobachtungen teilen</li><li>Ideen respektvoll einbringen</li><li>Ergreifen Sie die Initiative</li><li>Lücken füllen</li></ul><h2 id="die-fuhrungsmentalitat" tabindex="-1">Die Führungsmentalität <a class="header-anchor" href="#die-fuhrungsmentalitat" aria-label="Permalink to &quot;Die Führungsmentalität&quot;">​</a></h2><h3 id="verantwortung-statt-schuldzuweisung" tabindex="-1">Verantwortung statt Schuldzuweisung <a class="header-anchor" href="#verantwortung-statt-schuldzuweisung" aria-label="Permalink to &quot;Verantwortung statt Schuldzuweisung&quot;">​</a></h3><p>Führungskräfte übernehmen Verantwortung:</p><ul><li>„Wir haben nicht gut gespielt“, nicht „Sie haben daneben geschossen“.</li><li>„Ich hätte besser kommunizieren sollen“, nicht „Sie haben nicht zugehört“.</li></ul><h3 id="team-vor-selbst" tabindex="-1">Team vor Selbst <a class="header-anchor" href="#team-vor-selbst" aria-label="Permalink to &quot;Team vor Selbst&quot;">​</a></h3><p>Führungskräfte stellen den Erfolg des Teams in den Vordergrund:</p><ul><li>Feiern Sie die Erfolge des Teams</li><li>Teilen Sie den Kredit großzügig</li><li>Übernehmen Sie die Schuld persönlich</li><li>Die Bedürfnisse des Teams haben Priorität.</li></ul><h3 id="wachstum-statt-komfort" tabindex="-1">Wachstum statt Komfort <a class="header-anchor" href="#wachstum-statt-komfort" aria-label="Permalink to &quot;Wachstum statt Komfort&quot;">​</a></h3><p>Führungskräfte stellen sich der Herausforderung:</p><ul><li>Suche nach schwierigen Situationen</li><li>Aus Fehlern lernen</li><li>Streben nach Verbesserung</li><li>Modell kontinuierliches Wachstum</li></ul><h2 id="wenn-fuhrung-versagt" tabindex="-1">Wenn Führung versagt <a class="header-anchor" href="#wenn-fuhrung-versagt" aria-label="Permalink to &quot;Wenn Führung versagt&quot;">​</a></h2><p>Auch gute Führungskräfte scheitern manchmal:</p><ul><li>Falsche Entscheidungen werden getroffen</li><li>Trotz guter Führung verlieren die Teams.</li><li>Beziehungen werden belastet</li></ul><p><strong>Erholung:</strong></p><ol><li>Bestätige, was geschehen ist</li><li>Übernehmen Sie die entsprechende Verantwortung</li><li>Lerne die Lektionen</li><li>Gehe mit Demut voran</li></ol><hr><p>| <em>Verwandt: <a href="/en/education/team-player/">Teamdynamik</a> | <a href="/en/education/team-player/communication">Kommunikation</a> | <a href="/en/blog/team-chemistry">Aufbau von Teamchemie</a></em> |</p>',92)])])}]]);export{r as __pageData,a as default};
